<script>
(() => {const search=document.getElementById('student-search'),qiraat=document.getElementById('qiraat-filter'),narration=document.getElementById('narration-filter'),progress=document.getElementById('progress-filter'),rows=[...document.querySelectorAll('[data-student-row]')],empty=document.getElementById('no-results');let active='qiraats';const matchesStatus=(card)=>progress.value==='all'||(progress.value==='started'&&card.dataset.started==='1')||(progress.value==='not-started'&&card.dataset.started==='0')||(progress.value==='complete'&&card.dataset.complete==='1');const filter=()=>{let visible=0;rows.forEach((row)=>{const cards=[...row.querySelectorAll(active==='qiraats'?'[data-qiraat-card]':'[data-narration-card]')];let cardVisible=0;cards.forEach((card)=>{const matchesQiraat=qiraat.value==='all'||card.dataset.qiraatId===qiraat.value;const matchesNarration=active==='qiraats'||narration.value==='all'||card.dataset.narrationId===narration.value;const show=matchesQiraat&&matchesNarration&&matchesStatus(card);card.classList.toggle('hidden',!show);if(show)cardVisible++;});const showRow=(!search.value||row.dataset.name.includes(search.value.trim().toLocaleLowerCase('ar')))&&cardVisible>0;row.classList.toggle('hidden',!showRow);if(showRow)visible++;});empty.classList.toggle('hidden',visible!==0);};document.querySelectorAll('[data-tab]').forEach((button)=>button.addEventListener('click',()=>{active=button.dataset.tab;document.querySelectorAll('[data-tab]').forEach((item)=>item.classList.toggle('bg-white',item===button));document.querySelectorAll('[data-tab]').forEach((item)=>item.classList.toggle('text-emerald-950',item===button));document.querySelectorAll('[data-view]').forEach((view)=>view.classList.toggle('hidden',view.dataset.view!==active));narration.classList.toggle('hidden',active!=='narrations');filter();}));[search,qiraat,narration,progress].forEach((control)=>control.addEventListener('input',filter));[qiraat,narration,progress].forEach((control)=>control.addEventListener('change',filter));filter();})();
</script>
